{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Records were eligible for inclusion if they met the following criteria: - (i) the use of at least one POC testing device assessing NCD measures, including cardiovascular disease (e.g. lipid profiles, coagulation markers), chronic respiratory disease (e.g. FeNO), or diabetes (e.g. HbA1c, blood glucose). POC testing was considered across multiple contexts, including adult care, paediatric care, self-managed testing, clinic-based testing, or community health settings; - (ii) reporting of at least one measure related to health literacy or health literacy responsiveness, including outcomes mapped to the five WHO health literacy actions ( Access , Understand , Appraise , Remember , Use ). ... - (iii) health literacy of individuals aged 10 + years, including older children and adolescents, with caregivers able to report their own health literacy outcomes based on POC assessment of a child; - (iv) full-text peer reviewed journal article published within the five years prior to the search. Studies were excluded if they were reviews of peerreviewed studies. The five-year limit was applied in line with WHO guidance to capture contemporary evidence on POC testing and health literacy, reflecting advances in diagnostic technologies and evolving definitions of health literacy. No restrictions on the type of study design, sample size, or language of manuscript were imposed.",
      "reason": "The manuscript specifies key study characteristics used for eligibility (types of POC tests, clinical contexts/settings, age range, outcomes of interest, study design not restricted). However, it does not specify any follow-up requirements or minimum follow-up duration, so the characteristic 'follow-up requirements' is not addressed."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "full-text peer reviewed journal article published within the five years prior to the search. ... No restrictions on the type of study design, sample size, or language of manuscript were imposed.",
      "reason": "Eligibility criteria for report characteristics are explicitly stated: a five-year publication window and requirement for full-text peer-reviewed articles, and the manuscript states there were no language restrictions."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence explicitly distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "To address the research question, six studies adopted a qualitative approach, six utilised quantitative methods, and one used mixed methods (Table 1). All outcomes were treated as proxy measures of health literacy or",
      "reason": "The review specifies groups used in synthesis (qualitative, quantitative, mixed methods) and, together with Table 1 (table_0) and other text, groups studies by condition/POC test (diabetes, coagulation, mixed/other) and maps outcomes to WHO health literacy actions used for narrative synthesis, thereby linking groupings to the comparisons/objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The five-year limit was applied in line with WHO guidance to capture contemporary evidence on POC testing and health literacy, reflecting advances in diagnostic technologies and evolving definitions of health literacy.",
      "reason": "A rationale is provided for the notable restriction of including only studies published within the five years prior to the search (to capture contemporary evidence in line with WHO guidance)."
    }
  ],
  "confidence": "80"
}

